            @Override
            public double value(double x, double[] p) {
                double v = Double.NaN;
                try {
                    v = super.value(x, p);
                } catch (NotStrictlyPositiveException e) {
                    // ignore
                }
                return v;
            }

            @Override
            public double[] gradient(double x, double[] p) {
                double[] v = { Double.NaN, Double.NaN, Double.NaN };
                try {
                    v = super.gradient(x, p);
                } catch (NotStrictlyPositiveException e) {
                    // ignore
                }
                return v;
            }
        }, guess);
}"
