public JsonSerializer<?> createContextual(SerializerProvider serializers,
        BeanProperty property) throws JsonMappingException
{
    if (property == null) {
        return this;
    }
    JsonFormat.Value format = findFormatOverrides(serializers, property, handledType());
    if (format == null) {
        return this;
    }
    // Simple case first: serialize as numeric timestamp?
    JsonFormat.Shape shape = format.getShape();
    if (shape.isNumeric()) {
        return withFormat(Boolean.TRUE, null);
    }

    // 08-Jun-2017, tatu: With [databind#1648], this gets bit tricky..
    // First: custom pattern will override things
    if ((shape == JsonFormat.Shape.STRING) || format.hasPattern()
                    || format.hasLocale() || format.hasTimeZone()) {
        TimeZone tz = format.getTimeZone();
        final Locale loc = format.hasLocale()
                        ? format.getLocale()
                        : serializers.getLocale();
        if (format.hasPattern()) {
            final String pattern = format.getPattern();
            SimpleDateFormat df = new SimpleDateFormat(pattern, loc);
            if (tz == null) {
                tz = serializers.getTimeZone();
            }
            df.setTimeZone(tz);
            return withFormat(Boolean.FALSE, df);
        }
        // If no pattern, try to use the existing DateFormat but apply locale/timezone
        DateFormat df0 = serializers.getConfig().getDateFormat();
        if (df0 instanceof SimpleDateFormat) {
            SimpleDateFormat df = (SimpleDateFormat) df0;
            if (format.hasLocale()) {
                df = new SimpleDateFormat(df.toPattern(), loc);
            } else {
                df = (SimpleDateFormat) df.clone();
            }
            if (tz == null) {
                tz = serializers.getTimeZone();
            }
            df.setTimeZone(tz);
            return withFormat(Boolean.FALSE, df);
        }
        // For shape STRING without pattern and non-SimpleDateFormat, use ISO8601 with locale
        if (shape == JsonFormat.Shape.STRING) {
            final String pattern = StdDateFormat.DATE_FORMAT_STR_ISO8601;
            SimpleDateFormat df = new SimpleDateFormat(pattern, loc);
            if (tz == null) {
                tz = serializers.getTimeZone();
            }
            df.setTimeZone(tz);
            return withFormat(Boolean.FALSE, df);
        }
    }

    return this;
}

